/* ── Desktop: hide hamburger toggle ── */
.nav-toggle,
.nav-hamburger {
  display: none;
}

/* ── Mobile: ≤ 600px ── */
@media (max-width: 600px) {
  /* Prevent horizontal overflow */
  body {
    max-width: 100%;
    overflow-x: hidden;
  }

  main {
    max-width: 100%;
    overflow-x: hidden;
    padding: 1rem;
  }

  /* Header layout for hamburger */
  header {
    position: relative;
  }

  header h1 {
    font-size: 1.2rem;
    margin: 0 0 0.25rem 0;
  }

  /* Hamburger icon button */
  .nav-hamburger {
    display: block;
    position: absolute;
    top: 1rem;
    right: 1rem;
    font-size: 1.6rem;
    color: #d0e1ff;
    cursor: pointer;
    line-height: 1;
    user-select: none;
  }

  /* Hide the raw checkbox */
  .nav-toggle {
    display: none;
  }

  /* Collapse nav links by default on mobile */
  nav {
    display: none;
    flex-direction: column;
    margin-top: 0.5rem;
  }

  /* Show nav when checkbox is checked (CSS-only toggle) */
  .nav-toggle:checked ~ nav {
    display: flex;
  }

  nav a {
    display: block;
    padding: 0.75rem 0;
    margin-right: 0;
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    min-height: 44px;
    line-height: 44px;
    padding-top: 0;
    padding-bottom: 0;
  }

  /* Touch target sizing: minimum 44×44px (Apple HIG) */
  a,
  .btn,
  button {
    min-height: 44px;
    min-width: 44px;
  }

  .btn {
    padding: 0.75rem 1rem;
  }

  /* Form inputs: 16px minimum prevents iOS auto-zoom on focus */
  input,
  select,
  textarea {
    font-size: 16px;
  }

  /* Layout grids collapse earlier on narrow screens */
  .form-grid {
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  }

  .card-grid {
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  }
}

